function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is an integer from 1 to 100.';
  if (new Set(nums).size !== nums.length) return 'The values in nums must be distinct.';
  return null;
}

