function minimumRightShifts(nums) {
  const n = nums.length;
  let start = 0;
  for (let i = 1; i < n; i++) {
    if (nums[i] < nums[start]) {
      start = i;
    }
  }
  for (let step = 1; step < n; step++) {
    const previous = nums[(start + step - 1) % n];
    const current = nums[(start + step) % n];
    if (previous > current) {
      return -1;
    }
  }
  return (n - start) % n;
}

