function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 7);
  const pool = Array.from({ length: 100 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const values = pool.slice(0, n);
  // Most inputs are rotations of a sorted array so the answer is often not -1.
  if (rand() < 0.65) {
    values.sort((a, b) => a - b);
    const k = Math.floor(rand() * n);
    return [[...values.slice(k), ...values.slice(0, k)]];
  }
  return [values];
}
